// Laravel DispatchLectureClipExtractionJob payload.
// action=clip_lecture, lesson_id, video_url/youtube_url/rutube_url, spans[], callback_url.
const body = $input.first().json.body ?? $input.first().json;
if (body.action !== 'clip_lecture') {
  throw new Error('unexpected action: ' + (body.action ?? 'missing'));
}
const spans = Array.isArray(body.spans) ? body.spans : [];
if (!spans.length) {
  throw new Error('no spans — nothing to cut');
}
// Emit one item per span for the ffmpeg/VK loop. Real ffmpeg/VK credentials
// stay operator-owned (D12: agents never ship live VK tokens).
return spans.map((s, i) => ({
  json: {
    lesson_id: body.lesson_id,
    lesson_title: body.lesson_title ?? '',
    video_url: body.video_url || body.youtube_url || body.rutube_url || '',
    callback_url: body.callback_url,
    start_seconds: s.start_seconds,
    end_seconds: s.end_seconds,
    title: s.title || ('clip-' + (i + 1)),
    index: i + 1,
  },
}));

// Aggregate per-span results for a single Laravel callback.
// The two HTTP Request nodes replace $json with their own response, so the
// original span fields (lesson_id, start/end, title, callback_url) no longer
// exist on the incoming items — read them back from the source node by index
// (the pipeline is linear and 1:1, so order is preserved). VK ids come from
// the current items (the VK upload response).
const vkItems = $input.all();
const spans = $('Expand spans').all();
const clips = vkItems.map((it, i) => {
  const s = spans[i] ? spans[i].json : {};
  const v = it.json;
  return {
    start_seconds: s.start_seconds,
    end_seconds: s.end_seconds,
    title: s.title,
    vk_video_id: String(v.vk_video_id ?? v.id ?? v.video_id ?? ''),
    vk_owner_id: String(v.vk_owner_id ?? v.owner_id ?? ''),
  };
});
const first = spans[0] ? spans[0].json : {};
return [{
  json: {
    callback_url: first.callback_url,
    body: {
      lesson_id: first.lesson_id,
      clips,
    },
  },
}];
